const app=document.querySelector('#app');
const toast=document.querySelector('#toast');
const dialogRoot=document.querySelector('#dialog-root');
const IS_PRODUCTION=window.DWV33Integration?.environment==='production';
let integrationController=null;
let integrationSession={status:'loading',message:'Loading Dragonswood teacher identity…'};
let teacherName='Mr. Evans';
const arcadeTeacher=window.DWV33ArcadeTeacher;

const navItems=[
 ['student-command','🪄','Student Command'],['gradebook','📊','Gradebook'],['scribe','📜','Scribe Command'],['rewards','🎯','Class Rewards'],['passes','🎟️','Pass Control'],['jobs','🧹','Guild Jobs'],['schedule','🕘','Schedule'],['tools','🧰','Classroom Tools'],['leaderboards','🏆','Leaderboards']
];
const arcadeNav=['arcade','🕹️','Arcade Time'];
function teacherNavItems(){return arcadeTeacher?.enabled?[...navItems,arcadeNav]:navItems}
function arcadeEnvironmentLabel(){return IS_PRODUCTION?'Live Arcade controls':window.DWV33Integration?.environment==='manual-preview'?'Local preview state only':'Fictional emulator writes'}
function writeDestination(){return IS_PRODUCTION?'live Dragonswood records':'the fictional Firebase emulator'}
let students=[];
const state={
 page:'student-command',selected:new Set(),commandTab:'Rewards',pendingCommand:'',rosterFilter:'All',classPoints:64,universalPoints:24,
 activePasses:[{name:'Alaina',kind:'Bathroom',time:'1 min ago'}],pendingPasses:[{name:'Caleb',kind:'Water',time:'Now'},{name:'Nala',kind:'Bathroom',time:'2 min ago'}],
 payrollApproved:false,scheduleDay:'Today',gradeFilter:'All',scribeActive:false,leaderRange:'This Week',
 gradebook:null,scribe:null,
 operations:null,operationsBusy:false,
 arcadePeriodId:'period-1',arcadeRows:{},arcadeBusy:false
};
const references={
 'student-command':'assets/reference/teacher/dragonswood-teacher-02-gradebook.jpg',
 'gradebook':'assets/reference/teacher/dragonswood-teacher-01-student-command.jpg',
 'scribe':'assets/reference/teacher/dragonswood-teacher-04-class-rewards.jpg',
 'rewards':'assets/reference/teacher/dragonswood-teacher-05-pass-control.jpg',
 'jobs':'assets/reference/teacher/dragonswood-teacher-06-guild-jobs.jpg',
 'schedule':'assets/reference/teacher/dragonswood-teacher-07-schedule.jpg',
 'tools':'assets/reference/teacher/dragonswood-teacher-08-classroom-tools.jpg',
 'leaderboards':'assets/reference/teacher/dragonswood-teacher-09-leaderboards-final.jpg'
};
function showToast(message){toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2400)}
function openDialog(title,body,actions=''){dialogRoot.innerHTML=`<div class="dialog-backdrop" data-dialog-backdrop><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${title}</h2>${body}<div class="dialog-actions">${actions||'<button class="btn btn-primary" data-close-dialog>Done</button>'}</div></section></div>`;dialogRoot.querySelector('[data-close-dialog]')?.addEventListener('click',closeDialog);dialogRoot.querySelector('[data-dialog-backdrop]')?.addEventListener('click',e=>{if(e.target===e.currentTarget)closeDialog()});dialogRoot.querySelector('button')?.focus()}
function closeDialog(){dialogRoot.innerHTML=''}
function escapeHtml(value){return String(value??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function currentPage(){const h=location.hash.replace('#','');return teacherNavItems().some(n=>n[0]===h)?h:'student-command'}
function navMarkup(){return `<nav class="teacher-nav" aria-label="Teacher portal">${teacherNavItems().map(([id,icon,label])=>`<button class="nav-link ${state.page===id?'active':''}" data-page="${id}" ${state.page===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span><span class="nav-main">${label}</span></button>`).join('')}</nav>`}
function shell(){const preview=window.DWV33Integration?.environment==='manual-preview';return `<div class="portal teacher-shell teacher-page-${state.page}" data-${IS_PRODUCTION?'release':'tester-build'}="v3.3"><aside class="teacher-sidebar"><div class="teacher-brand"><div class="teacher-brand-row"><img class="teacher-command-crest" src="assets/art/teacher-command-crest.png" alt=""><div><h2>TEACHER PORTAL</h2><p>Explore Academy</p></div></div></div>${navMarkup()}<div class="prototype-badge">✦ <b>${IS_PRODUCTION?'V3.3 STUDENT BETA':'V3.3 SAFE TESTER'}</b><small>${arcadeTeacher?.enabled?arcadeEnvironmentLabel():IS_PRODUCTION?'Live teacher records':'Local mock data only'}</small></div></aside><main class="teacher-main" id="page-content"><header class="teacher-topbar"><div class="teacher-header-inner"><div><div class="teacher-header-caption">EXPLORE ACADEMY · EVANS 4–5 · TEACHER PORTAL</div><div class="teacher-command-lockup"><img class="teacher-command-crest" src="assets/art/teacher-command-crest.png" alt=""><h1>DRAGONSWOOD COMMAND</h1></div></div><div class="teacher-account"><span class="online-dot"></span><span>${escapeHtml(teacherName)}</span><span>⌄</span></div></div></header><div class="teacher-content">${pageMarkup()}</div></main>${referenceButton()}${IS_PRODUCTION?'':`<div class="tester-ribbon">${arcadeTeacher?.enabled?preview?'V3.3 ARCADE • LOCAL PREVIEW':'V3.3 ARCADE • EMULATOR WRITES':'V3.3 TESTER • NO LIVE WRITES'}</div>`}</div>`}
function referenceButton(){return new URLSearchParams(location.search).get('reference')==='1'?`<button type="button" class="btn btn-gold btn-sm reference-button" data-reference>Reference</button>`:''}
function pageBanner(icon,eyebrow,title,sub,action=''){return `<section class="teacher-page-banner"><div class="teacher-page-title"><div class="teacher-page-icon">${icon}</div><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2><p>${sub}</p></div></div>${action}</section>`}
function metric(icon,label,value,sub){return `<article class="panel metric"><div class="metric-icon">${icon}</div><div><div class="eyebrow">${label}</div><strong>${value}</strong><small>${sub}</small></div></article>`}
function pageMarkup(){switch(state.page){case'gradebook':return gradebookPage();case'scribe':return scribePage();case'rewards':return rewardsPage();case'passes':return passesPage();case'jobs':return jobsPage();case'schedule':return schedulePage();case'tools':return toolsPage();case'leaderboards':return leaderboardsPage();case'arcade':return arcadePage();default:return studentCommandPage()}}

function studentCommandPage(){const ops=state.operations,visible=filteredRosterStudents();return `<section class="panel attention-strip"><div class="attention-item"><span class="metric-icon">⭐</span><div><b>Recognition requests</b><small>${ops?`${ops.recognition.length} waiting`:'2 waiting'}</small></div><span class="gold attention-action" data-review-recognition>REVIEW</span></div><div class="attention-item"><span class="metric-icon">🔒</span><div><b>Daily access</b><small>${ops?(ops.dailyUnlocked?'Whole class unlocked':'Morning Work gate active'):'Whole class unlocked'}</small></div><button class="gold attention-action" type="button" data-manage-daily-access>MANAGE</button></div><div class="attention-item"><span class="metric-icon">✓</span><div><b>Curriculum overrides</b><small>${ops?(ops.curriculumOverrides.length?`${ops.curriculumOverrides.length} waiting`:'None waiting'):'None waiting'}</small></div>${ops?.curriculumOverrides?.length?'<button class="gold attention-action" type="button" data-review-curriculum>REVIEW</button>':''}</div><div class="attention-score"><strong>${ops?ops.classHp:48}</strong><small>CLASS HP</small></div><div class="attention-score"><strong>20</strong><small>LEVEL CAP</small></div><div class="attention-score"><strong>${ops?ops.dailyXp:150}</strong><small>DAILY XP</small></div></section>
<section class="teacher-workspace"><article class="panel step-card"><div class="step-head"><div><div class="eyebrow">Step 1</div><h3>Choose Students</h3></div><span class="selected-badge">${state.selected.size} selected</span></div><div class="search-row"><input class="search-input" id="student-search" placeholder="⌕ Search the guild roster" aria-label="Search students"></div><div class="roster-filters">${['All','4th','5th','Boys','Girls'].map(filter=>`<button class="filter-mini ${state.rosterFilter===filter?'active':''}" type="button" data-roster-filter="${filter}">${filter}</button>`).join('')}</div><div class="row between mb-12"><button class="btn btn-quiet btn-sm" data-select-visible>Select visible</button><button class="btn btn-quiet btn-sm" data-clear-selected>Clear</button></div><div class="roster-list" id="roster-list">${rosterRows(visible)}</div></article><article class="panel command-panel"><div class="step-head step-head-pad"><div><div class="eyebrow">Step 2</div><h3>Choose a Command</h3></div><span class="muted text-9">Selection stays active while you switch tools</span></div><div class="teacher-tabs">${['Rewards','Corrections','Custom','Management'].map(t=>`<button class="teacher-tab ${state.commandTab===t?'active':''}" data-command-tab="${t}">${tabIcon(t)} ${t}</button>`).join('')}</div><div class="command-body">${commandCards()}</div></article></section>
<div class="review-dock"><div><div class="eyebrow">Ready to review</div><strong>${!state.selected.size?'Select scholars first':state.pendingCommand||'Choose a command'}</strong></div><div class="row"><span class="muted text-10">${state.selected.size} students selected</span><button class="btn btn-primary" data-review ${state.selected.size&&state.pendingCommand?'':'disabled'}>REVIEW CHANGES</button></div></div>`}
function tabIcon(t){return({Rewards:'🏆',Corrections:'⚖️',Custom:'⚙️',Management:'🧙'})[t]}
function rosterRows(list){return list.map(s=>`<label class="roster-row ${state.selected.has(s.id)?'selected':''}" data-roster-name="${escapeHtml(s.name)}"><input class="roster-check" type="checkbox" ${state.selected.has(s.id)?'checked':''} data-student="${escapeHtml(s.id)}"><span class="roster-avatar">${escapeHtml(s.name[0]||'?')}</span><span><span class="roster-name">${escapeHtml(s.name)}</span><span class="roster-meta">${escapeHtml(s.meta)}</span></span></label>`).join('')}
function selectedNames(){const ids=state.selected;return students.filter(s=>ids.has(s.id)).map(s=>s.name)}
function filteredRosterStudents(search=''){const q=String(search||'').trim().toLowerCase();return students.filter(student=>{const byText=!q||student.name.toLowerCase().includes(q),filter=state.rosterFilter,byGroup=filter==='All'||filter==='4th'&&String(student.grade)==='4'||filter==='5th'&&String(student.grade)==='5'||filter==='Boys'&&student.genderGroup==='boy'||filter==='Girls'&&student.genderGroup==='girl';return byText&&byGroup})}
function commandCards(){const cards={Rewards:[['✅','Ready & Working','Materials out, started quickly, focused.','+15 XP • +3 Gold'],['🚶','Excellent Transition','Quiet, quick, ready at the next location.','+10 XP • +2 Gold'],['🍎','Great Lunch Behavior','Respectful and responsible lunch choices.','+20 XP • +4 Gold'],['🎨','Great Specials Behavior','Represented our class well during specials.','+20 XP • +4 Gold'],['📚','Outstanding Effort','Persistence, improvement, or excellent focus.','+30 XP • +6 Gold'],['🛡️','Dragonswood Leadership','Helped the class through a brave, kind choice.','+40 XP • +8 Gold']],Corrections:[['↩️','Reset Focus','Remove a small amount of daily XP.','−10 XP'],['⏳','Pause Access','Temporarily pause one optional feature.','No stat change'],['🧭','Teacher Check-In','Require a teacher conversation before an optional activity.','Status only'],['📝','Reflection Needed','Assign a short reflection checkpoint.','Status only']],Custom:[['✨','Custom XP Change','Choose a specific XP amount.','Teacher entered'],['🪙','Custom Gold Change','Choose a specific Gold amount.','Teacher entered'],['❤️','Custom HP Change','Adjust classroom HP carefully.','Teacher entered'],['🏷️','Recognition Note','Record a positive teacher note.','No stat change']],Management:[['🔓','Unlock Daily Access','Restore daily optional destinations.','Access only'],['🔒','Pause Optional Area','Pause one optional destination.','Access only'],['👤','Profile Review','Open scholar profile and history.','Read only'],['📌','Teacher Flag','Add a teacher-only follow-up marker.','Teacher only']]};return `<div class="section-heading no-top"><div><div class="eyebrow">${state.commandTab==='Rewards'?'Positive recognition':'Teacher tools'}</div><h2>${state.commandTab==='Rewards'?'Quick Rewards':state.commandTab}</h2></div></div><div class="command-grid">${cards[state.commandTab].map(c=>`<button class="command-card" data-command="${c[1]}" type="button"><span class="text-22">${c[0]}</span><h4>${c[1]}</h4><p>${c[2]}</p><div class="command-effect">${c[3]}</div><span class="command-add">＋</span></button>`).join('')}</div>`}

function gradebookPage(){
  const fallback=[['Abigail','A','94','98','91','93','2','5','girls'],['Alaina','A','87','86','84','90','—','4','girls'],['Alejandro','A','91','95','88','89','—','5','boys'],['Aliya','A','78','74','80','82','—','5','girls'],['Caleb','C','83','89','77','84','—','5','boys'],['Christian','C','96','98','91','93','1','4','boys'],['Damian','D','72','86','84','90','—','4','boys'],['DragonTest','D','88','95','88','89','2','5','girls']];
  const grades=state.gradebook?.rows?.length?state.gradebook.rows.map(row=>[row.name,row.initial,String(row.total),String(row.daily),String(row.curriculum),String(row.reading),row.missing?String(row.missing):'—',String(row.grade),row.genderGroup]):fallback;
  const filtered=state.gradeFilter==='All'?grades:grades.filter(g=>g[7]===state.gradeFilter);
  const metrics=state.gradebook?{students:String(grades.length),average:`${state.gradebook.classAverage}%`,missing:String(state.gradebook.missing),affected:`${state.gradebook.studentsWithMissing} students affected`}:{students:'22',average:'86%',missing:'7',affected:'5 students affected'};
  return `${pageBanner('📚','Academic records','Dragonswood Gradebook','See the class first. Open one scholar only when you need assignment details.','<button class="btn btn-primary btn-sm" data-toast="Gradebook refreshed from secure academic records.">↻ Refresh</button>')}<section class="metric-grid">${metric('👥','Students',metrics.students,state.gradebook?'Live roster':'12 fourth • 10 fifth')}${metric('✦','Class average',metrics.average,state.gradebook?'Weighted 40 / 40 / 20':'B • up 3%')}${metric('📜','Assigned work','18','Across 3 categories')}${metric('⚠️','Actual missing',metrics.missing,metrics.affected)}</section><section class="teacher-workspace"><aside class="panel weight-panel"><div class="eyebrow">GRADE SETTINGS</div><h3>Category Weights</h3>${[['Daily Quest',40],['Curriculum Quest',40],['Reading Tests',20]].map(w=>`<div class="weight-row"><div class="weight-label"><span>${w[0]}</span><b class="gold">${w[1]}%</b></div><progress class="dw-progress dw-progress-weight" max="100" value="${w[1]}" aria-label="${w[0]} weight">${w[1]}%</progress></div>`).join('')}<button class="btn btn-secondary w-full">Edit Category Weights</button><div class="legend"><div class="eyebrow">QUICK LEGEND</div><div><i class="legend-a"></i>90–100 A</div><div><i class="legend-b"></i>80–89 B</div><div><i class="legend-c"></i>70–79 C</div><div><i class="legend-d"></i>Below 70</div></div></aside><article class="panel gradebook-panel"><div class="gradebook-toolbar"><input class="search-input" placeholder="⌕ Search students" aria-label="Search students"><div class="grade-filter-segments" aria-label="Grade filter">${[['All','All grades'],['4','4th'],['5','5th']].map(([v,label])=>`<button type="button" class="${state.gradeFilter===v?'active':''}" data-grade-segment="${v}">${label}</button>`).join('')}</div><button class="btn btn-secondary btn-sm" data-toast="CSV export remains locked in this candidate.">↓ Export CSV</button></div><table class="grade-table"><thead><tr><th>Scholar</th><th>Total</th><th>Daily</th><th>Curriculum</th><th>Reading</th><th>Missing</th></tr></thead><tbody>${filtered.map(g=>`<tr><td><div class="student-cell"><span class="roster-avatar">${escapeHtml(g[1])}</span><span><b>${escapeHtml(g[0])}</b><small class="roster-meta">Grade ${escapeHtml(g[7])} • ${g[8]==='girls'?'Girls':'Boys'}</small></span></div></td><td><span class="grade-score ${gradeClass(g[2])}">${g[2]}%</span></td><td>${g[3]}%</td><td>${g[4]}%</td><td>${g[5]}%</td><td>${g[6]==='—'?'—':`<span class="missing-pill">${g[6]}</span>`}</td></tr>${g[0]==='Alaina'?`<tr class="grade-detail-row"><td colspan="6"><div class="grade-detail"><div class="grade-detail-head"><div><small>LATEST ASSIGNMENT</small><b>Daily Quest • Day 14</b></div><div><small>SCORE</small><b>86/100</b></div><div><small>TEACHER ACTION</small><button class="btn btn-quiet btn-sm" data-toast="Assignment list opened in tester mode.">View All Assignments →</button></div></div></div></td></tr>`:''}`).join('')}</tbody></table></article></section>`;
}
function gradeClass(v){const n=Number(v);return n>=90?'grade-a':n>=80?'grade-b':n>=70?'grade-c':'grade-d'}

function scribePage(){const live=state.scribe||{},active=state.scribeActive,responses=live.responses||[],classSize=state.scribe?students.length:22;const displayResponses=state.scribe?responses:['Abigail','Joshua','Alaina','Christian'].map((studentName,i)=>({id:`local-${i}`,studentName,status:i<2?'submitted':'draft',wordCount:89+i*12}));return `${pageBanner('✍️','Writing missions','Scribe Arena Command','Launch a mission, watch scholars write, and review everything from one calm workspace.',active?'<button class="btn btn-secondary btn-sm" data-close-mission>Close mission</button>':'<span class="selected-badge">○ No active mission</span>')}<section class="split-main"><article class="panel teacher-form"><div class="eyebrow">Step 1</div><h3>Build the Mission</h3><div class="form-grid"><div class="field"><label>Mission title</label><input id="scribe-title" value="Morning Quickwrite"></div><div class="field"><label>Mode</label><select id="scribe-mode"><option>Quickwrite</option><option>Draft</option></select></div><div class="field"><label>Writing type</label><select id="scribe-type"><option>Narrative</option><option>Opinion</option><option>Informative</option></select></div><div class="field"><label>Target skill</label><select id="scribe-skill"><option>Sensory Details</option><option>Strong Evidence</option></select></div><div class="field"><label>Time</label><input id="scribe-time" value="5"></div><div class="field"><label>Minimum</label><input id="scribe-minimum" value="75"></div><div class="field span-3"><label>Prompt</label><textarea id="scribe-prompt">Describe a place that feels mysterious. Use at least three sensory details.</textarea></div></div><div class="row mt-12"><button class="btn btn-primary" data-launch-scribe ${active?'disabled':''}>🔥 Launch to Class</button><button class="btn btn-secondary" data-close-mission>Close Mission</button></div></article><aside class="panel writing-status"><div class="eyebrow">Step 2</div><h3>Live Writing Status</h3><div class="empty-status"><span class="text-26">📜</span><div><div class="eyebrow">${active?'Live':'Waiting'}</div><b>${active?'Mission active':'No active mission'}</b><div class="muted text-9">${active?'Students can begin writing now.':'Launch a writing mission to begin.'}</div></div></div><div class="donut"><span>${active?(state.scribe?live.submitted:4):'0'}<small class="donut-caption">of ${classSize} submitted</small></span></div><div class="status-stats"><div class="status-stat"><b>${active?(state.scribe?live.drafting:8):'0'}</b><small class="roster-meta">Drafting</small></div><div class="status-stat"><b>${active?(state.scribe?live.aiScored:2):'0'}</b><small class="roster-meta">AI scored</small></div><div class="status-stat"><b>${active?(state.scribe?live.avgWords:104):'0'}</b><small class="roster-meta">Avg words</small></div></div></aside></section><article class="panel responses-panel"><div class="eyebrow">Step 3</div><h3>Student Responses</h3>${active?`<div class="stack mt-12">${displayResponses.map(row=>`<div class="pass-card"><div class="pass-row"><div class="pass-student"><span class="roster-avatar">${escapeHtml(row.studentName?.[0]||'?')}</span><div><b>${escapeHtml(row.studentName)}</b><p>${row.status==='submitted'?'Submitted':'Drafting'} • ${row.wordCount} words</p></div></div><button class="btn btn-secondary btn-sm" data-review-writing="${escapeHtml(row.id)}">Review</button></div></div>`).join('')}</div>`:'<div class="empty-center"><div><div class="gold text-28">✦</div><strong>The scriptorium is quiet.</strong><small>Student responses will appear here after you launch the mission.</small></div></div>'}</article>`}

function rewardsPage(){const live=state.operations?.goals,classPoints=live?.shared??state.classPoints,universal=live?.universal??state.universalPoints,goals=live?.rows||[{id:'secondRecess',icon:'🌤️',title:'Second Recess',points:8,goal:10,pct:80},{id:'classPet',icon:'🐾',title:'Class Pet',points:172,goal:250,pct:69},{id:'fieldTrip',icon:'🚌',title:'Field Trip',points:418,goal:750,pct:56}];return `${pageBanner('🛡️','Whole-class motivation','Class Rewards & Goals','See every point bank and milestone without scrolling through separate control panels.','<button class="btn btn-primary btn-sm" data-toast="Milestone editor opened.">＋ Add Milestone</button>')}<article class="panel class-points"><div class="class-point-number"><span class="trophy">🏆</span><div><div class="eyebrow">Shared class points</div><strong>${classPoints}</strong><small class="roster-meta">${Math.max(0,75-classPoints)} points until the next class milestone</small></div></div><div><progress class="dw-progress dw-progress-class" max="100" value="${Math.min(100,classPoints/75*100)}" aria-label="Class points goal progress">${Math.min(100,classPoints/75*100)}%</progress></div><div class="class-point-controls"><input class="search-input" id="class-points-reason" placeholder="Reason (optional)"><button class="btn btn-secondary btn-sm" data-points="1">+1</button><button class="btn btn-secondary btn-sm" data-points="5">+5</button><button class="btn btn-secondary btn-sm" data-points="10">+10</button><button class="btn btn-secondary btn-sm" data-points="-1">−1</button><button class="btn btn-secondary btn-sm" data-toast="Last local point change undone.">Undo</button></div></article><section class="grid-3 mt-12">${goals.map((goal,index)=>goalCard(goal.icon,index===0?'Daily goal':'Long-term goal',goal.title,`${goal.points} / ${goal.goal}`,goal.pct,goal.id)).join('')}</section><section class="grid-2 mt-12"><article class="panel flex-bank"><span class="star">🌟</span><div><div class="eyebrow">Universal point bank</div><strong class="universal-points">${universal}</strong><small class="roster-meta">Move flexible points into any class goal.</small></div><select class="search-input" id="universal-goal"><option value="secondRecess">Second Recess</option><option value="classPet">Class Pet</option><option value="fieldTrip">Field Trip</option></select><input class="search-input points-input" id="universal-amount" value="5"><button class="btn btn-primary" data-assign-universal>Assign</button></article><article class="panel milestone-list"><div class="eyebrow">Upcoming</div><h3>Class Milestones</h3>${[['🎮','Choice Time','75 shared points'],['📚','Extra Read-Aloud','100 shared points'],['🐉','Dragonswood Celebration','150 shared points']].map(m=>`<div class="milestone-row"><span class="text-23">${m[0]}</span><div><b>${m[1]}</b><small>${m[2]}</small></div><span class="muted lock-label">Locked</span></div>`).join('')}</article></section>`}
function goalCard(icon,kicker,title,count,pct,id=''){return `<article class="panel goal-card"><div class="goal-top"><div class="row"><span class="metric-icon">${icon}</span><div><div class="eyebrow">${kicker}</div><h3>${title}</h3></div></div><b class="gold">${count}</b></div><progress class="dw-progress" max="100" value="${pct}" aria-label="${title} progress">${pct}%</progress><div class="goal-controls"><button class="btn btn-secondary btn-sm" data-goal-points="1" data-goal-id="${id}">+1</button><button class="btn btn-secondary btn-sm" data-goal-points="2" data-goal-id="${id}">+2</button><button class="btn btn-secondary btn-sm" data-goal-points="5" data-goal-id="${id}">+5</button><button class="btn btn-secondary btn-sm" data-goal-points="-1" data-goal-id="${id}">−1</button></div></article>`}

function passesPage(){const ops=state.operations,returned=ops?.returned??14,attention=ops?.needsAttention??0,blackout=ops?.passBlackout?.active===true,slots=ops?.bathroomSlots||[];return `${pageBanner('🎟️','Student movement','Pass Control','Approve, deny, return, and review passes without duplicate status changes.',`<div class="row"><button class="btn btn-secondary btn-sm" data-pass-history>History</button><button class="btn ${blackout?'btn-danger':'btn-secondary'} btn-sm" data-pass-blackout>${blackout?'End Pass Blackout':'Start Pass Blackout'}</button></div>`)}<section class="metric-grid">${metric('⏳','Pending',state.pendingPasses.length,'Needs a teacher decision')}${metric('🚶','Active',state.activePasses.length,'Currently out of class')}${metric('✓','Returned',returned,'Today')}${metric('⚠️','Needs attention',attention,attention?'Overdue or stale slot':'No stuck requests')}</section>${blackout?`<div class="pass-card serious-warning"><b>🔒 Pass blackout is active</b><p>${escapeHtml(ops?.passBlackout?.reason||'Teacher-directed pause')}</p></div>`:''}<section class="pass-columns"><article class="panel pass-list"><div class="section-heading no-top"><div><div class="eyebrow">Queue</div><h2>Pending Requests</h2></div></div>${state.pendingPasses.length?state.pendingPasses.map((p,i)=>`<div class="pass-card"><div class="pass-row"><div class="pass-student"><span class="roster-avatar">${escapeHtml(p.name?.[0]||'?')}</span><div><div class="pass-kind">${escapeHtml(p.kind)} pass</div><b>${escapeHtml(p.name)}</b><p>Requested ${escapeHtml(p.time)} • student is waiting</p></div></div><div class="pass-actions"><button class="btn btn-primary btn-sm" data-pass-approve="${i}">Approve</button><button class="btn btn-danger btn-sm" data-pass-deny="${i}">Deny</button></div></div></div>`).join(''):'<div class="empty-center"><div>✓<strong>No students waiting.</strong></div></div>'}</article><article class="panel pass-list"><div class="section-heading no-top"><div><div class="eyebrow">Live</div><h2>Active Passes</h2></div></div>${state.activePasses.length?state.activePasses.map((p,i)=>`<div class="pass-card active-pass"><div class="pass-row"><div class="pass-student"><span class="roster-avatar">${escapeHtml(p.name?.[0]||'?')}</span><div><div class="pass-kind">${escapeHtml(p.kind)} pass</div><b>${escapeHtml(p.name)}</b><p>Approved ${escapeHtml(p.time)} • currently active</p></div></div><button class="btn btn-secondary btn-sm" data-pass-return="${i}">Mark Returned</button></div></div>`).join(''):'<div class="empty-center"><div>✦<strong>No active passes.</strong></div></div>'}</article></section><section class="panel mt-12"><div class="eyebrow">Bathroom slots</div><h3>One-at-a-time status</h3><div class="grid-2 mt-12">${['boy','girl'].map(group=>{const slot=slots.find(row=>row.id===group)||{};return `<div class="pass-card"><b>${group==='boy'?'Boys':'Girls'} slot</b><p>${slot.occupied===true?`Occupied by ${escapeHtml(slot.studentName||'Student')}`:'Available'}</p></div>`}).join('')}</div></section>`}

function jobsPage(){const live=state.operations?.jobs,jobs=live?live.rows.map(j=>[j.icon,j.name,`${j.pay} Gold per completed week`,j.studentName,`${j.completedCount} / 4 days`,j.id,j.studentId]):[['🧹','Floor Warden','3 Gold per completed week','Caleb','4 / 4 days'],['📚','Lore Keeper','8 Gold per completed week','Aliya','4 / 4 days'],['💻','Tech Mage','5 Gold per completed week','Damian','4 / 4 days'],['🚪','Gate Keeper','4 Gold per completed week','Grayson','4 / 4 days'],['🌱','Garden Guardian','2 Gold per completed week','Nala','3 / 4 days'],['📦','Supply Smith','6 Gold per completed week','Raul','4 / 4 days']],payroll=live?live.payroll.map(row=>[row.studentName,row.name,`${row.pay} Gold`]):[['Caleb','Floor Warden','5 Gold'],['Kinsley','Lore Keeper','5 Gold'],['Joshua','Tech Mage','5 Gold'],['Alaina','Gate Keeper','5 Gold'],['Nala','Garden Guardian','2 Gold']];return `${pageBanner('🧹','Classroom responsibility','Guild Jobs & Payroll','Assign every role, see weekly completion, and handle payroll from one roster.','<button class="btn btn-primary btn-sm" data-payroll>Run Payroll Preview</button>')}<section class="metric-grid">${metric('🛡️','Jobs filled',live?`${live.filled} / ${live.rows.length}`:'6 / 6',live&&live.filled!==live.rows.length?'Open assignments':'Every role assigned')}${metric('✅','Completed',live?live.completed:'27','This week')}${metric('🪙','Payroll due',live?live.payrollTotal:'28','Gold on Friday')}${metric('⚠️','Needs check-in',live?live.needsCheckIn:'2','Missed yesterday')}</section><section class="split-main"><article class="panel job-roster"><div class="eyebrow">Assignments</div><h3>Guild Roster</h3>${jobs.map(j=>`<div class="job-row"><div class="job-title"><span>${j[0]}</span><div><b>${escapeHtml(j[1])}</b><small>${escapeHtml(j[2])}</small></div></div><select data-job-id="${escapeHtml(j[5]||'')}" aria-label="Assign ${escapeHtml(j[1])}"><option value="">Unassigned</option>${students.map(s=>`<option value="${escapeHtml(s.id)}" ${s.id===(j[6]||'')?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select><div class="job-complete">${escapeHtml(j[4])}</div></div>`).join('')}</article><aside class="panel payroll-panel"><div class="eyebrow">This week</div><h3>Payroll Preview</h3><div class="payroll-total"><small class="roster-meta">Total scheduled</small><strong>${live?live.payrollTotal:28} Gold</strong></div>${payroll.map(p=>`<div class="payroll-row"><div class="payroll-person"><span class="roster-avatar">${escapeHtml(p[0]?.[0]||'?')}</span><div><b>${escapeHtml(p[0])}</b><small>${escapeHtml(p[1])}</small></div></div><b class="gold text-9">${escapeHtml(p[2])}</b></div>`).join('')}<button class="btn btn-primary" data-payroll ${state.payrollApproved?'disabled':''}>${state.payrollApproved?'✓ Friday Payroll Approved':'Approve Friday Payroll'}</button><div class="center muted prototype-note">${live?(IS_PRODUCTION?'Live records — duplicate payroll is blocked.':'Fictional emulator only — duplicate payroll is blocked.'):'Prototype only — no Gold will be issued.'}</div></aside></section>`}

function schedulePage(){const live=state.operations?.schedule,blocks=live?(state.scheduleDay==='Tomorrow'?live.tomorrow:live.today).map(row=>[row.icon,row.title,[row.time,row.end].filter(Boolean).join('–')||'—',row]):[['🌅','Morning Math','8:00–8:25'],['📚','ELA','8:30–10:00'],['🍎','Recess / Lunch','10:00–11:00'],['🔭','Science','11:05–12:00'],['🏛️','Social Studies','12:05–1:00'],['🎨','Specials','1:10–2:10']],events=live?live.events.map(row=>[row.icon,row.title,[row.dateKey,row.time].filter(Boolean).join(' • ')]):[['🏐','Volleyball Game','Aug 25 • 4:30 PM'],['📸','Fall Pictures','Aug 29'],['🌙','No-school day','Coming up']];return `${pageBanner('🕘','Classroom rhythm','Schedule & Calendar','Keep the day and class events visible together.','<div class="row"><button class="btn btn-primary btn-sm" data-toast="New block editor opened.">＋ Add Block</button><button class="btn btn-secondary btn-sm" data-toast="New event editor opened.">＋ Add Event</button></div>')}<section class="schedule-grid"><article class="panel timeline-teacher"><div class="section-heading no-top"><div><div class="eyebrow">${state.scheduleDay}</div><h2>Daily Timeline</h2></div><div class="filter-tabs">${['Today','Tomorrow'].map(d=>`<button class="filter-tab ${state.scheduleDay===d?'active':''}" data-schedule-day="${d}">${d}</button>`).join('')}</div></div>${blocks.map(b=>`<div class="timeline-teacher-row"><span class="metric-icon schedule-mini-icon">${escapeHtml(b[0])}</span><div><b>${escapeHtml(b[1])}</b><small>${escapeHtml(b[2])}</small></div><button class="btn btn-quiet btn-sm" data-toast="Schedule block edit simulated.">•••</button></div>`).join('')}<div class="row row-end mt-10"><button class="btn btn-secondary btn-sm" data-toast="Day copied locally.">Copy to another day</button><button class="btn btn-primary btn-sm" data-save-schedule${live?'':' data-toast="Schedule saved locally."'}>Save Today</button></div></article><article class="panel calendar-card"><div class="eyebrow">Class calendar</div><h3>August 2026</h3><div class="calendar-grid">${['S','M','T','W','T','F','S'].map(d=>`<span class="head">${d}</span>`).join('')}${Array.from({length:35},(_,i)=>{const d=i-4;return `<span class="${d===24?'today':''} ${d===27?'selected':''}">${d>0&&d<32?d:''}</span>`}).join('')}</div><div class="calendar-events">${events.map(e=>`<div class="event-row"><div>${escapeHtml(e[0])}</div><div><b>${escapeHtml(e[1])}</b><small>${escapeHtml(e[2])}</small></div></div>`).join('')}</div></article></section>`}

function toolsPage(){const groups=[['Projection & Focus',[['⏱️','Visual Timer','Launch a large classroom timer.'],['🔊','Volume Meter','Give students a visible sound-level target.'],['🎯','Focus Screen','Project one clean direction at a time.']]],['Random & Groups',[['🎲','Random Scholar','Choose fairly from the current class roster.'],['👥','Group Maker','Create balanced temporary groups.'],['🔢','Number Picker','Pick a random number or range.']]],['Classroom Helpers',[['📝','Quick Poll','Run a fast teacher-led pulse check.'],['🎵','Ambient Sound','Launch calm, optional classroom ambience.'],['📣','Attention Signal','Project a quick visual attention cue.']]]];return `${pageBanner('🧰','Teacher utilities','Classroom Tools','Launch common tools quickly without turning the page into a wall of buttons.','<button class="btn btn-primary btn-sm" data-tool="Seating Command">Open Seating Command & Room Builder</button>')} ${groups.map(g=>`<div class="section-heading"><div><div class="eyebrow">${g[0]}</div><h2>${g[0]}</h2></div></div><section class="tools-grid">${g[1].map(t=>`<article class="panel tool-card"><div class="tool-icon">${t[0]}</div><h3>${t[1]}</h3><p>${t[2]}</p><button class="btn btn-secondary btn-sm" data-tool="${t[1]}">Launch</button></article>`).join('')}</section>`).join('')}`}

function leaderboardsPage(){const board=state.operations?.leaderboard,leaders=board?.rows?.length?board.rows.slice(0,5).map(row=>[String(row.rank),row.name[0]||'?',row.name,`${Number(row.score).toLocaleString()} XP`]):[['1','K','Kinsley','1,840 XP'],['2','J','Joshua','1,720 XP'],['3','N','Nala','1,610 XP'],['4','A','Alaina','1,590 XP'],['5','C','Caleb','1,530 XP']],podium=board?.rows?.length?[board.rows[1]||board.rows[0],board.rows[0],board.rows[2]||board.rows[0]]:null,podiumCard=(row,place,klass,fallback)=>row?`<div class="podium-person ${klass}"><div class="podium-avatar">${escapeHtml(row.name?.[0]||'?')}</div><b>${escapeHtml(row.name)}</b><small>${Number(row.score).toLocaleString()} XP</small><div class="podium-block">${place}</div></div>`:fallback;return `${pageBanner('🏆','Positive recognition','Leaderboard Command','Celebrate class effort while keeping reward rules explicit and repeat-safe.','<div class="filter-tabs"><button class="filter-tab active">This Week</button><button class="filter-tab">All Time</button></div>')}<article class="panel teacher-podium">${podium?podiumCard(podium[0],2,'second','')+podiumCard(podium[1],1,'first','')+podiumCard(podium[2],3,'third',''):'<div class="podium-person second"><div class="podium-avatar">K</div><b>Kinsley</b><small>1,840 XP</small><div class="podium-block">2</div></div><div class="podium-person first"><div class="podium-avatar">J</div><b>Joshua</b><small>1,920 XP</small><div class="podium-block">1</div></div><div class="podium-person third"><div class="podium-avatar">N</div><b>Nala</b><small>1,730 XP</small><div class="podium-block">3</div></div>'}</article><section class="split-main mt-12"><article class="panel leader-table"><div class="row between"><div><div class="eyebrow">This week</div><h3>XP Standings</h3></div><button class="btn btn-primary btn-sm" data-reward-leaders>Reward top scholars</button></div>${leaders.map(l=>`<div class="leader-row"><div class="rank-num">#${escapeHtml(l[0])}</div><div class="roster-avatar">${escapeHtml(l[1])}</div><b>${escapeHtml(l[2])}</b><span class="gold text-10">${escapeHtml(l[3])}</span></div>`).join('')}</article><aside class="panel reward-rules"><div class="eyebrow">Reward rules</div><h3>Recognition</h3>${[['🥇','1st Place','Bonus badge + 20 XP'],['🥈','2nd & 3rd','Bonus badge + 10 XP'],['📚','Reading streak','Class shout-out'],['🌱','Biggest growth','Class shout-out']].map(r=>`<div class="reward-rule">${r[0]} <b>${r[1]}</b><small>${r[2]}</small></div>`).join('')}<div class="selected-badge mt-12">Duplicate rewards blocked</div></aside></section>`}

function arcadePage(){
  const selected=students.filter(s=>state.selected.has(s.id));
  const rows=selected.map(s=>{
    const a=state.arcadeRows[s.id]||{},criteria=a.criteria||{},tokens=Math.max(0,Math.min(3,Number(a.tokens)||0));
    const previewSession=window.DWV33Integration?.environment==='manual-preview'&&(a.sessionId||a.lastSessionId)?`<small>Preview refund ID: <code>${escapeHtml(a.sessionId||a.lastSessionId)}</code></small>`:'';
    return `<div class="pass-card"><div class="pass-row"><div class="pass-student"><span class="roster-avatar">${escapeHtml(s.name[0]||'?')}</span><div><b>${escapeHtml(s.name)}</b><p>${tokens} / 3 Tokens • ${a.active?'Session active':a.teacherEnabled?'Arcade open':'Arcade locked'}</p>${previewSession}</div></div><div class="row"><span class="selected-badge">${criteria.ready?'✓':'○'} Ready</span><span class="selected-badge">${criteria.responsible?'✓':'○'} Responsible</span><span class="selected-badge">${criteria.complete?'✓':'○'} Complete</span><button class="btn btn-secondary btn-sm" data-arcade-individual="${escapeHtml(s.id)}" data-enabled="${a.individualEnabled===false?'true':'false'}">${a.individualEnabled===false?'Unlock':'Lock'}</button></div></div></div>`;
  }).join('');
  return `${pageBanner('🕹️','Free-time currency','Arcade Time Command','Award up to three Tokens per period and control Arcade like a field trip or second recess.','<button class="btn btn-secondary btn-sm" data-arcade-refresh>↻ Refresh selected</button>')}<section class="panel teacher-form"><div class="form-grid"><div class="field"><label for="arcade-period">Period ID</label><input id="arcade-period" value="${escapeHtml(state.arcadePeriodId)}" maxlength="48"></div><div class="field span-3"><label>Class availability</label><div class="row"><button class="btn btn-primary" data-arcade-class="true" ${state.arcadeBusy?'disabled':''}>Open Arcade Time</button><button class="btn btn-danger" data-arcade-class="false" ${state.arcadeBusy?'disabled':''}>Lock Arcade Now</button></div></div></div><div class="eyebrow mt-12">Award one Token criterion to every selected scholar</div><div class="row mt-12">${[['ready','Ready'],['responsible','Responsible'],['complete','Complete']].map(([id,label])=>`<button class="btn btn-secondary" data-arcade-award="${id}" ${!selected.length||state.arcadeBusy?'disabled':''}>＋ ${label}</button>`).join('')}</div><p class="muted prototype-note">Each criterion can be awarded once per Phoenix school date and period. A full 3-Token wallet cannot stockpile more.</p></section><section class="panel pass-list mt-12"><div class="row between"><div><div class="eyebrow">Selected scholars</div><h3>${selected.length} selected</h3></div><button class="btn btn-secondary btn-sm" data-page="student-command">Change selection</button></div><div class="stack mt-12">${rows||'<div class="empty-center"><div><strong>Select scholars first.</strong><small>Use Student Command, then return here.</small></div></div>'}</div></section><section class="panel teacher-form mt-12"><div class="eyebrow">Technical issue only</div><h3>One-time session refund</h3><p class="muted">Select exactly one scholar, paste the audited session ID, and give a reason. The server caps the wallet at 3 and blocks a second refund.</p><div class="form-grid"><div class="field"><label for="arcade-refund-session">Session ID</label><input id="arcade-refund-session" placeholder="Arcade session document ID"></div><div class="field"><label for="arcade-refund-reason">Reason</label><input id="arcade-refund-reason" placeholder="Technical issue"></div><div class="field"><label>&nbsp;</label><button class="btn btn-danger" data-arcade-refund ${selected.length===1&& !state.arcadeBusy?'':'disabled'}>Review Refund</button></div></div></section>`;
}

function authGate(){const status=integrationSession.status||'loading',message=integrationSession.message||'Checking Teacher Command access…',canSignIn=status==='signed-out'||status==='unauthorized'||status==='error';return `<div class="portal teacher-shell" data-${IS_PRODUCTION?'release':'tester-build'}="v3.3"><main class="teacher-main" id="page-content"><div class="teacher-content"><section class="panel tool-card"><div class="eyebrow">${IS_PRODUCTION?'SECURE TEACHER PORTAL':'SECURE INTEGRATION CANDIDATE'}</div><div class="tool-icon">🛡️</div><h3>${status==='unauthorized'?'Teacher access denied':'Teacher Command Sign In'}</h3><p>${escapeHtml(message)}</p>${canSignIn?'<button class="btn btn-primary" data-signin>Sign in with Google</button>':''}<p class="muted prototype-note">${IS_PRODUCTION?'Authorized teacher • live Dragonswood records':`${escapeHtml(window.DWV33Integration?.environment||'loading')} • no production writes enabled`}</p></section></div></main>${IS_PRODUCTION?'':'<div class="tester-ribbon">V3.3 INTEGRATION • SAFE MODE</div>'}</div>`}
function render(){state.page=currentPage();if(integrationSession.status!=='authorized'){app.innerHTML=authGate();bindAuthGate();document.title=IS_PRODUCTION?'Dragonswood Command | Sign In':'[INTEGRATION] Dragonswood Command | Sign In';return}app.innerHTML=shell();bind();document.title=`${IS_PRODUCTION?'':'[TESTER] '}Dragonswood Command | ${teacherNavItems().find(n=>n[0]===state.page)[2]}`}
function bindAuthGate(){app.querySelector('[data-signin]')?.addEventListener('click',async()=>{try{await integrationController?.signIn()}catch(err){showToast(`Sign-in failed: ${err?.code||err?.message||err}`)}})}
function teacherAccountDialog(){openDialog('Teacher Account',`<p>${escapeHtml(integrationSession.user?.email||'Authorized teacher')}</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-primary" id="teacher-signout">Sign out</button>`);dialogRoot.querySelector('#teacher-signout')?.addEventListener('click',async()=>{closeDialog();try{await integrationController?.signOut()}catch(err){showToast(`Sign-out failed: ${err?.message||err}`)}})}
function applyTeacherSession(session){teacherName=session.teacherName||'Mr. Evans';students=Array.isArray(session.students)?session.students:[];if(session.academic){state.gradebook=session.academic.gradebook||null;state.scribe=session.academic.scribe||null;state.scribeActive=!!state.scribe?.session}if(session.operations){state.operations=session.operations;state.classPoints=session.operations.goals?.shared??state.classPoints;state.universalPoints=session.operations.goals?.universal??state.universalPoints;state.pendingPasses=[...(session.operations.pending||[])];state.activePasses=[...(session.operations.active||[])];state.payrollApproved=!!session.operations.jobs?.rows?.length&&!session.operations.jobs?.payroll?.length}if(!IS_PRODUCTION&&!state.selected.size){const defaults=window.DWV33Integration?.environment==='manual-preview'?['Jacob Preview']:['Alaina','Christian','Nala'];for(const wanted of defaults){const row=students.find(s=>s.name===wanted);if(row)state.selected.add(row.id)}}}

function bind(){
 app.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>location.hash=el.dataset.page));
 app.querySelectorAll('[data-toast]').forEach(el=>el.addEventListener('click',()=>showToast(el.dataset.toast)));
 app.querySelector('[data-reference]')?.addEventListener('click',showReference);
 app.querySelector('.teacher-account')?.addEventListener('click',teacherAccountDialog);
 app.querySelectorAll('[data-student]').forEach(el=>el.addEventListener('change',()=>{el.checked?state.selected.add(el.dataset.student):state.selected.delete(el.dataset.student);render()}));
 app.querySelector('[data-clear-selected]')?.addEventListener('click',()=>{state.selected.clear();render()});
 app.querySelector('[data-select-visible]')?.addEventListener('click',()=>{filteredRosterStudents(document.querySelector('#student-search')?.value).forEach(s=>state.selected.add(s.id));render()});
 app.querySelector('#student-search')?.addEventListener('input',e=>filterRoster(e.target.value));
 app.querySelectorAll('[data-roster-filter]').forEach(el=>el.addEventListener('click',()=>{state.rosterFilter=el.dataset.rosterFilter;render()}));
 app.querySelectorAll('[data-command-tab]').forEach(el=>el.addEventListener('click',()=>{state.commandTab=el.dataset.commandTab;render()}));
 app.querySelectorAll('[data-grade-segment]').forEach(el=>el.addEventListener('click',()=>{state.gradeFilter=el.dataset.gradeSegment;render()}));
 app.querySelectorAll('[data-command]').forEach(el=>el.addEventListener('click',()=>{state.pendingCommand=el.dataset.command;reviewCommand(el.dataset.command)}));
 app.querySelector('[data-review]')?.addEventListener('click',()=>reviewCommand(state.pendingCommand));
 app.querySelector('[data-launch-scribe]')?.addEventListener('click',()=>confirmScribe(true));app.querySelectorAll('[data-close-mission]').forEach(el=>el.addEventListener('click',()=>confirmScribe(false)));
 app.querySelectorAll('[data-review-writing]').forEach(el=>el.addEventListener('click',()=>reviewWriting(el.dataset.reviewWriting)));
 app.querySelectorAll('[data-points]').forEach(el=>el.addEventListener('click',()=>adjustClassPoints(Number(el.dataset.points))));
 app.querySelectorAll('[data-goal-points]').forEach(el=>el.addEventListener('click',()=>adjustGoalPoints(el.dataset.goalId,Number(el.dataset.goalPoints))));
 app.querySelector('[data-assign-universal]')?.addEventListener('click',assignUniversalPoints);
 app.querySelectorAll('[data-pass-approve]').forEach(el=>el.addEventListener('click',()=>approvePass(Number(el.dataset.passApprove))));app.querySelectorAll('[data-pass-deny]').forEach(el=>el.addEventListener('click',()=>denyPass(Number(el.dataset.passDeny))));app.querySelectorAll('[data-pass-return]').forEach(el=>el.addEventListener('click',()=>returnPass(Number(el.dataset.passReturn))));
 app.querySelector('[data-review-recognition]')?.addEventListener('click',recognitionReview);
 app.querySelector('[data-pass-history]')?.addEventListener('click',showPassHistory);
 app.querySelector('[data-pass-blackout]')?.addEventListener('click',managePassBlackout);
 app.querySelector('[data-manage-daily-access]')?.addEventListener('click',manageDailyAccess);
 app.querySelector('[data-review-curriculum]')?.addEventListener('click',reviewCurriculumOverrides);
 app.querySelector('[data-payroll]')?.addEventListener('click',payrollReview);app.querySelectorAll('[data-job-id]').forEach(el=>el.addEventListener('change',()=>assignJob(el.dataset.jobId,el.value)));app.querySelectorAll('[data-schedule-day]').forEach(el=>el.addEventListener('click',()=>{state.scheduleDay=el.dataset.scheduleDay;render()}));app.querySelector('[data-save-schedule]')?.addEventListener('click',saveCurrentSchedule);
 app.querySelector('[data-reward-leaders]')?.addEventListener('click',rewardLeadersReview);
 app.querySelectorAll('[data-tool]').forEach(el=>el.addEventListener('click',()=>launchClassroomTool(el.dataset.tool)));
 app.querySelector('#arcade-period')?.addEventListener('input',e=>{state.arcadePeriodId=e.target.value});
 app.querySelector('[data-arcade-refresh]')?.addEventListener('click',refreshArcadeTeacher);
 app.querySelectorAll('[data-arcade-award]').forEach(el=>el.addEventListener('click',()=>awardArcade(el.dataset.arcadeAward)));
 app.querySelectorAll('[data-arcade-class]').forEach(el=>el.addEventListener('click',()=>setArcadeClass(el.dataset.arcadeClass==='true')));
 app.querySelectorAll('[data-arcade-individual]').forEach(el=>el.addEventListener('click',()=>setArcadeIndividual(el.dataset.arcadeIndividual,el.dataset.enabled==='true')));
 app.querySelector('[data-arcade-refund]')?.addEventListener('click',reviewArcadeRefund);
}
async function runArcade(action,success){
 if(!arcadeTeacher?.enabled){showToast('Arcade controls are unavailable in this environment.');return}
 state.arcadeBusy=true;render();
 try{await action();showToast(success)}catch(err){showToast(err?.message||'Arcade command failed.')}finally{state.arcadeBusy=false;render()}
}
async function refreshArcadeTeacher(){
 const chosen=students.filter(s=>state.selected.has(s.id));
 if(!chosen.length){showToast('Select at least one scholar first.');return}
 state.arcadePeriodId=(document.querySelector('#arcade-period')?.value||state.arcadePeriodId).trim()||'period-1';
 await runArcade(async()=>{const pairs=await Promise.all(chosen.map(async s=>[s.id,await arcadeTeacher.getState(s.id,state.arcadePeriodId)]));for(const [id,value] of pairs)state.arcadeRows[id]=value},'Arcade status refreshed.');
}
async function awardArcade(criterion){
 const ids=[...state.selected];state.arcadePeriodId=(document.querySelector('#arcade-period')?.value||state.arcadePeriodId).trim()||'period-1';
 if(!ids.length){showToast('Select at least one scholar first.');return}
 await runArcade(async()=>{await Promise.all(ids.map(uid=>arcadeTeacher.award(uid,criterion,state.arcadePeriodId)));const pairs=await Promise.all(ids.map(async uid=>[uid,await arcadeTeacher.getState(uid,state.arcadePeriodId)]));for(const [id,value] of pairs)state.arcadeRows[id]=value},`${criterion[0].toUpperCase()+criterion.slice(1)} Token criterion processed.`);
}
function setArcadeClass(enabled){
 const destination=window.DWV33Integration?.environment==='manual-preview'?'this browser’s isolated preview state':writeDestination();
 openDialog(`${enabled?'Open':'Lock'} Arcade Time?`,`<p>${enabled?'The class may start Arcade when each scholar has 3 Tokens.':'Every active Arcade session will be stopped by the authoritative server lock.'}</p><p class="muted">This command writes only to ${destination}.</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn ${enabled?'btn-primary':'btn-danger'}" id="confirm-arcade-class">${enabled?'Open class access':'Lock class now'}</button>`);
 dialogRoot.querySelector('#confirm-arcade-class')?.addEventListener('click',async()=>{closeDialog();await runArcade(()=>arcadeTeacher.setAvailability(enabled),`Class Arcade Time ${enabled?'opened':'locked'}.`)});
}
async function setArcadeIndividual(uid,enabled){await runArcade(async()=>{await arcadeTeacher.setAvailability(enabled,uid);state.arcadeRows[uid]=await arcadeTeacher.getState(uid,state.arcadePeriodId)},`Scholar Arcade access ${enabled?'opened':'locked'}.`)}
function reviewArcadeRefund(){
 const uid=[...state.selected][0],sessionId=document.querySelector('#arcade-refund-session')?.value.trim(),reason=document.querySelector('#arcade-refund-reason')?.value.trim();
 if(!uid||!sessionId||!reason){showToast('Choose one scholar, session ID, and technical reason.');return}
 openDialog('Confirm technical refund?',`<p>This returns only the spent Tokens that fit below the 3-Token cap. The server records the reason and permanently blocks a second refund for this session.</p><p class="muted">Session: ${escapeHtml(sessionId)}<br>Reason: ${escapeHtml(reason)}</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-danger" id="confirm-arcade-refund">Issue one-time refund</button>`);
 dialogRoot.querySelector('#confirm-arcade-refund')?.addEventListener('click',async()=>{closeDialog();await runArcade(async()=>{await arcadeTeacher.refund(uid,sessionId,reason);state.arcadeRows[uid]=await arcadeTeacher.getState(uid,state.arcadePeriodId)},'Technical refund recorded.')});
}
function filterRoster(q){const target=document.querySelector('#roster-list');if(target)target.innerHTML=rosterRows(filteredRosterStudents(q));target?.querySelectorAll('[data-student]').forEach(el=>el.addEventListener('change',()=>{el.checked?state.selected.add(el.dataset.student):state.selected.delete(el.dataset.student);render()}))}
function commandEffect(command){return ({'Ready & Working':'+15 XP and +3 Gold','Excellent Transition':'+10 XP and +2 Gold','Great Lunch Behavior':'+20 XP, +4 Gold, and +1 Class Pet point','Great Specials Behavior':'+20 XP, +4 Gold, and +1 Field Trip point','Outstanding Effort':'+30 XP and +6 Gold','Dragonswood Leadership':'+40 XP, +8 Gold, and +1 Universal point','Reset Focus':'−10 XP, never below zero','Pause Access':'Pause optional destinations until a teacher unlocks them','Teacher Check-In':'Require a teacher check-in before optional destinations','Reflection Needed':'Require reflection before optional destinations','Unlock Daily Access':'Unlock today and clear optional-access holds','Pause Optional Area':'Pause optional destinations until a teacher unlocks them','Recognition Note':'Record a positive note in the scholar transaction history','Teacher Flag':'Save a teacher-only follow-up marker'})[command]||'Apply the reviewed teacher command'}
function reviewCommand(command){
 if(!state.selected.size){showToast('Select at least one scholar first.');return}
 if(!command){showToast('Choose a command first.');return}
 if(command==='Profile Review'){openProfileReview();return}
 const serious=/Pause|Reset|Reflection/.test(command),custom=/^Custom /.test(command),needsNote=/Note|Flag|Check-In|Reflection|Pause/.test(command);
 openDialog('Review Before Applying',`<div class="selected-badge">${state.selected.size} students selected</div><h3 class="mt-12">${escapeHtml(command)}</h3><p class="muted">${escapeHtml(selectedNames().join(', '))}</p><div class="pass-card"><b>Exact effect</b><p>${escapeHtml(commandEffect(command))}</p></div>${custom?'<div class="field mt-12"><label>Adjustment amount</label><input id="command-amount" type="number" step="1" placeholder="Use a negative number to subtract"></div>':''}<div class="field mt-12"><label>${needsNote?'Teacher note / reason':'Reason (optional)'}</label><textarea id="command-reason" placeholder="Why is this command being applied?"></textarea></div>${serious?'<label class="pass-card serious-warning"><input id="command-serious-confirm" type="checkbox"> I reviewed this access or consequence change and want to apply it.</label>':''}`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn ${serious?'btn-danger':'btn-primary'}" id="apply-student-command">Apply reviewed command</button>`);
 dialogRoot.querySelector('#apply-student-command')?.addEventListener('click',()=>applyReviewedCommand(command,serious));
}
async function applyReviewedCommand(command,serious){
 if(serious&&!dialogRoot.querySelector('#command-serious-confirm')?.checked){showToast('Confirm the serious-action checkbox first.');return}
 const button=dialogRoot.querySelector('#apply-student-command');if(button){button.disabled=true;button.textContent='Applying…'}
 try{const result=await integrationController.applyStudentCommand(command,[...state.selected],{amount:dialogRoot.querySelector('#command-amount')?.value,reason:dialogRoot.querySelector('#command-reason')?.value,note:dialogRoot.querySelector('#command-reason')?.value});state.pendingCommand='';closeDialog();showToast(`${command} applied to ${result.students} scholar${result.students===1?'':'s'}.`)}catch(err){if(button){button.disabled=false;button.textContent='Apply reviewed command'}showToast(err?.message||'Command could not be applied.')}
}
function openProfileReview(){const chosen=students.filter(student=>state.selected.has(student.id));openDialog('Scholar Profile Review',`<div class="stack">${chosen.map(student=>`<article class="pass-card"><b>${escapeHtml(student.name)}</b><p>${escapeHtml(student.meta)} • ${student.xp} XP • ${student.gold} Gold • ${student.hp} HP</p><p>Class: ${escapeHtml(student.classId||'Unchosen')} • Pet: ${escapeHtml(student.activePet||'None')}</p>${student.teacherFlag?`<p><b>Teacher flag:</b> ${escapeHtml(student.teacherFlag)}</p>`:''}<p>${student.optionalAccessPaused?'🔒 Optional access paused':''} ${student.teacherCheckInRequired?'🧭 Check-in required':''} ${student.reflectionRequired?'📝 Reflection required':''}</p></article>`).join('')}</div>`,`<button class="btn btn-primary" data-close-dialog>Close profile review</button>`)}
function confirmScribe(active){if(active){const payload={title:document.querySelector('#scribe-title')?.value||'Morning Quickwrite',mode:document.querySelector('#scribe-mode')?.value||'Quickwrite',writingType:document.querySelector('#scribe-type')?.value||'Narrative',targetSkill:document.querySelector('#scribe-skill')?.value||'Sensory Details',timeMinutes:document.querySelector('#scribe-time')?.value||5,minWords:document.querySelector('#scribe-minimum')?.value||75,prompt:document.querySelector('#scribe-prompt')?.value||''};openDialog('Launch writing mission?',`<p>Students will see <b>${escapeHtml(payload.title)}</b>. This writes to ${writeDestination()}.</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-primary" id="confirm-launch">Launch mission</button>`);dialogRoot.querySelector('#confirm-launch').addEventListener('click',async()=>{try{if(integrationController?.launchWritingSession)await integrationController.launchWritingSession(payload);else state.scribeActive=true;closeDialog();render();showToast('Writing mission launched.')}catch(err){closeDialog();showToast(err?.message||'Mission could not launch.')}})}else openDialog('Close writing mission?',`<p>Students will no longer be able to start or change this mission.</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-danger" id="confirm-close-scribe">Close mission</button>`),dialogRoot.querySelector('#confirm-close-scribe')?.addEventListener('click',async()=>{try{if(integrationController?.closeWritingSession)await integrationController.closeWritingSession();else state.scribeActive=false;closeDialog();render();showToast('Mission closed.')}catch(err){closeDialog();showToast(err?.message||'Mission could not close.')}})}
function reviewWriting(id){const row=state.scribe?.responses?.find(item=>item.id===id);if(!row){showToast('Response opened for review.');return}openDialog(`Review ${escapeHtml(row.studentName)}`,`<p>${escapeHtml(row.responseText)}</p><div class="form-grid"><div class="field"><label>Score (0–20)</label><input id="writing-review-score" value="${row.teacherScore??''}"></div><div class="field span-3"><label>Teacher feedback</label><textarea id="writing-review-feedback">${escapeHtml(row.teacherFeedback||'')}</textarea></div></div>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-primary" id="save-writing-review">Save review</button>`);dialogRoot.querySelector('#save-writing-review')?.addEventListener('click',async()=>{try{await integrationController.reviewWriting(id,dialogRoot.querySelector('#writing-review-score')?.value,dialogRoot.querySelector('#writing-review-feedback')?.value);closeDialog();showToast(`Teacher review saved to ${writeDestination()}.`)}catch(err){closeDialog();showToast(err?.message||'Review could not save.')}})}
async function adjustClassPoints(delta){if(!state.operations||!integrationController?.adjustClassPoints){state.classPoints=Math.max(0,state.classPoints+delta);showToast(`Class points now ${state.classPoints} in prototype.`);render();return}try{const reason=document.querySelector('#class-points-reason')?.value||'Teacher adjustment';await integrationController.adjustClassPoints(delta,reason);showToast(`Class points saved to ${writeDestination()}.`)}catch(err){showToast(err?.message||'Class points could not save.')}}
async function adjustGoalPoints(goalId,delta){try{await integrationController.adjustGoal(goalId,delta);showToast(`Class goal ${delta>0?'+':''}${delta} saved.`)}catch(err){showToast(err?.message||'Class goal could not update.')}}
async function assignUniversalPoints(){if(!state.operations||!integrationController?.assignUniversal){showToast('5 universal points assigned locally.');return}try{const goal=document.querySelector('#universal-goal')?.value,amount=document.querySelector('#universal-amount')?.value;await integrationController.assignUniversal(goal,amount);showToast('Universal points moved to the class goal.')}catch(err){showToast(err?.message||'Universal points could not move.')}}
async function approvePass(i){const p=state.pendingPasses[i];if(!p)return;if(!p.collection||!integrationController?.reviewPass){state.pendingPasses.splice(i,1);state.activePasses.push({...p,time:'just now'});showToast(`${p.name}'s ${p.kind.toLowerCase()} pass approved locally.`);render();return}try{await integrationController.reviewPass(p.collection,p.id,true);showToast(`${p.name}'s ${p.kind.toLowerCase()} request approved.`)}catch(err){showToast(err?.message||'Pass request could not be approved.')}}
async function denyPass(i){const p=state.pendingPasses[i];if(!p)return;if(!p.collection||!integrationController?.reviewPass){state.pendingPasses.splice(i,1);showToast(`${p.name}'s request denied locally.`);render();return}try{await integrationController.reviewPass(p.collection,p.id,false);showToast(`${p.name}'s request denied.`)}catch(err){showToast(err?.message||'Pass request could not be denied.')}}
async function returnPass(i){const p=state.activePasses[i];if(!p)return;if(!p.collection||!integrationController?.returnPass){state.activePasses.splice(i,1);showToast(`${p.name} marked returned locally.`);render();return}try{await integrationController.returnPass(p.collection,p.id);showToast(`${p.name} marked returned.`)}catch(err){showToast(err?.message||'Pass could not be closed.')}}
function showPassHistory(){const rows=state.operations?.passHistory||[];openDialog('Pass History',`<div class="stack">${rows.length?rows.slice(0,50).map(row=>`<article class="pass-card"><b>${escapeHtml(row.studentName||'Student')} • ${escapeHtml(row.label||row.type||'Pass')}</b><p>${escapeHtml(row.dateKey||'')} • ${escapeHtml(row.status||'returned')}${row.durationMinutes!==undefined&&row.durationMinutes!==null?` • ${Number(row.durationMinutes)} min`:''}</p></article>`).join(''):'<div class="pass-card"><p>No archived passes are available yet.</p></div>'}</div>`,`<button class="btn btn-primary" data-close-dialog>Close history</button>`)}
function managePassBlackout(){const active=state.operations?.passBlackout?.active===true;if(active){openDialog('End Pass Blackout?',`<p>Students will be able to use normal pass rules again.</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-primary" id="confirm-pass-blackout">End blackout</button>`)}else{openDialog('Start Pass Blackout?',`<p>New pass starts will pause until you end the blackout. Active students can still return their passes.</p><div class="field"><label>Reason shown to students</label><input id="pass-blackout-reason" value="Teacher-directed classroom pause"></div>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-danger" id="confirm-pass-blackout">Start blackout</button>`)}dialogRoot.querySelector('#confirm-pass-blackout')?.addEventListener('click',async()=>{try{await integrationController.setPassBlackout(!active,dialogRoot.querySelector('#pass-blackout-reason')?.value||'');closeDialog();showToast(`Pass blackout ${active?'ended':'started'}.`)}catch(err){showToast(err?.message||'Pass blackout could not update.')}})}
function recognitionReview(){const rows=state.operations?.recognition||[];if(!rows.length){showToast('No recognition requests are waiting.');return}openDialog('Recognition Requests',`<div class="stack">${rows.map(row=>`<div class="pass-card"><div class="pass-row"><div><b>${escapeHtml(row.name)}</b><p>${escapeHtml(row.reason)} • ${escapeHtml(row.time)}</p></div><div class="pass-actions"><button class="btn btn-primary btn-sm" data-recognition-approve="${escapeHtml(row.id)}">Approve +1 XP</button><button class="btn btn-danger btn-sm" data-recognition-dismiss="${escapeHtml(row.id)}">Dismiss</button></div></div></div>`).join('')}</div>`);dialogRoot.querySelectorAll('[data-recognition-approve]').forEach(button=>button.addEventListener('click',()=>reviewRecognition(button.dataset.recognitionApprove,true)));dialogRoot.querySelectorAll('[data-recognition-dismiss]').forEach(button=>button.addEventListener('click',()=>reviewRecognition(button.dataset.recognitionDismiss,false)))}
async function reviewRecognition(id,approve){try{await integrationController.reviewRecognition(id,approve);closeDialog();showToast(approve?'Recognition approved and +1 XP recorded.':'Recognition request dismissed.')}catch(err){closeDialog();showToast(err?.message||'Recognition request could not be reviewed.')}}
function manageDailyAccess(){
 const chosen=students.filter(student=>state.selected.has(student.id));
 openDialog('Manage Daily Access',`<p>Morning Work remains the normal gate. Use an override only when you intentionally want to open optional destinations today.</p><div class="pass-card"><b>${chosen.length?`${chosen.length} selected scholar${chosen.length===1?'':'s'}`:'No scholars selected'}</b><p>${escapeHtml(chosen.map(row=>row.name).join(', ')||'Select scholars first to use an individual override.')}</p></div>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-secondary" id="lock-daily-access">Clear override</button><button class="btn btn-primary" id="unlock-selected" ${chosen.length?'':'disabled'}>Unlock selected</button><button class="btn btn-primary" id="unlock-class">Unlock whole class</button>`);
 dialogRoot.querySelector('#unlock-selected')?.addEventListener('click',()=>saveDailyAccess(false,chosen.map(row=>row.id)));
 dialogRoot.querySelector('#unlock-class')?.addEventListener('click',()=>saveDailyAccess(true,[]));
 dialogRoot.querySelector('#lock-daily-access')?.addEventListener('click',()=>saveDailyAccess(false,[]));
}
async function saveDailyAccess(all,ids){try{await integrationController.setDailyAccess(all,ids);closeDialog();showToast(all?'Whole-class daily access unlocked.':ids.length?'Selected scholars unlocked.':'Daily access override cleared.')}catch(err){showToast(err?.message||'Daily access could not update.')}}
function reviewCurriculumOverrides(){const rows=state.operations?.curriculumOverrides||[];if(!rows.length){showToast('No curriculum reviews are waiting.');return}openDialog('Curriculum Review Queue',`<div class="stack">${rows.map(row=>`<article class="pass-card"><b>${escapeHtml(row.studentName||row.studentEmail||'Student')} • ${escapeHtml(row.lessonTitle||row.lessonId||'Curriculum Quest')}</b>${row.questionPrompt?`<p><b>Question:</b> ${escapeHtml(row.questionPrompt)}</p>`:''}<p><b>Student answer:</b> ${escapeHtml(row.studentAnswer||'No answer recorded')}</p>${row.expectedAnswer?`<p><b>Expected:</b> ${escapeHtml(row.expectedAnswer)}</p>`:''}<textarea data-curriculum-note="${escapeHtml(row.id)}" placeholder="Optional note for the student"></textarea><div class="pass-actions"><button class="btn btn-primary btn-sm" data-curriculum-decision="approved" data-curriculum-id="${escapeHtml(row.id)}">Approve as correct</button><button class="btn btn-secondary btn-sm" data-curriculum-decision="returned" data-curriculum-id="${escapeHtml(row.id)}">Return question</button></div></article>`).join('')}</div>`);dialogRoot.querySelectorAll('[data-curriculum-decision]').forEach(button=>button.addEventListener('click',()=>resolveCurriculumOverride(button.dataset.curriculumId,button.dataset.curriculumDecision)))}
async function resolveCurriculumOverride(id,status){try{const note=dialogRoot.querySelector(`[data-curriculum-note="${CSS.escape(id)}"]`)?.value||'';await integrationController.reviewCurriculumOverride(id,status,note);closeDialog();showToast(status==='approved'?'Curriculum answer approved.':'Question returned for revision.')}catch(err){showToast(err?.message||'Curriculum review could not save.')}}
async function assignJob(jobId,studentId){if(!state.operations||!integrationController?.assignJob){showToast('Job assignment changed locally.');return}try{await integrationController.assignJob(jobId,studentId);showToast('Guild job assignment saved.')}catch(err){showToast(err?.message||'Guild job could not be assigned.')}}
async function saveCurrentSchedule(){if(!state.operations||!integrationController?.saveSchedule){showToast('Schedule saved locally.');return}const tomorrow=state.scheduleDay==='Tomorrow',date=new Date(Date.now()+(tomorrow?86400000:0)),dayName=new Intl.DateTimeFormat('en-US',{timeZone:'America/Phoenix',weekday:'long'}).format(date),blocks=tomorrow?state.operations.schedule.tomorrow:state.operations.schedule.today;try{await integrationController.saveSchedule(dayName,blocks);showToast(`${dayName} schedule saved to ${writeDestination()}.`)}catch(err){showToast(err?.message||'Schedule could not save.')}}
function payrollReview(){const live=state.operations?.jobs,rows=live?.payroll||[],count=live?rows.length:5,total=live?.payrollTotal??28;openDialog('Approve Friday Payroll?',`<p><b>${count} scholars • ${total} Gold scheduled</b></p><p class="muted">Each weekly payment uses a deterministic record, so duplicate payroll is blocked.</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-primary" id="confirm-payroll">${live?'Approve payroll':'Approve simulation'}</button>`);dialogRoot.querySelector('#confirm-payroll').addEventListener('click',async()=>{if(!live||!integrationController?.runPayroll){state.payrollApproved=true;closeDialog();render();showToast('Payroll approved in prototype only.');return}try{const result=await integrationController.runPayroll();closeDialog();showToast(`${result.paid} payroll payment${result.paid===1?'':'s'} issued • ${result.total} Gold.`)}catch(err){closeDialog();showToast(err?.message||'Payroll could not run.')}})}
function rewardLeadersReview(){const rows=state.operations?.leaderboard?.rows?.slice(0,3)||[],fallback=[['Joshua',20],['Kinsley',10],['Nala',10]],display=rows.length?rows.map((row,index)=>[row.name,[20,10,10][index]]):fallback;openDialog('Reward top scholars?',`<p>Each weekly reward uses one deterministic record. A second click cannot pay the same scholar twice.</p><div class="stack">${display.map(row=>`<div class="pass-card">${escapeHtml(row[0])} • +${row[1]} XP</div>`).join('')}</div>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-primary" id="confirm-leader-rewards">${state.operations?'Issue rewards':'Simulate reward'}</button>`);dialogRoot.querySelector('#confirm-leader-rewards')?.addEventListener('click',async()=>{if(!state.operations||!integrationController?.rewardLeaders){closeDialog();showToast('Leaderboard reward simulated.');return}try{const count=await integrationController.rewardLeaders();closeDialog();showToast(`${count} new weekly leaderboard reward${count===1?'':'s'} issued.`)}catch(err){closeDialog();showToast(err?.message||'Leaderboard rewards could not be issued.')}})}
let classroomToolTimer=null,ambientContext=null,volumeStream=null,volumeAnimation=null;
function launchClassroomTool(tool){
 if(tool==='Seating Command'){const href=new URL('../seating-command/index.html',document.baseURI).href;openDialog('Seating Command & Room Builder',`<iframe title="Seating Command and Room Builder" src="${escapeHtml(href)}" style="width:min(1100px,82vw);height:72vh;border:0;border-radius:12px;background:#07101f"></iframe>`,`<button class="btn btn-primary" data-close-dialog>Close seating tools</button>`);return}
 if(tool==='Visual Timer'){openDialog('Visual Timer',`<div class="field"><label>Minutes</label><input id="tool-timer-minutes" type="number" min="1" max="180" value="10"></div><div id="tool-timer-display" class="center gold" style="font-size:64px;font-weight:900;margin:20px">10:00</div>`,`<button class="btn btn-secondary" data-close-dialog>Close</button><button class="btn btn-primary" id="start-tool-timer">Start timer</button>`);dialogRoot.querySelector('#start-tool-timer')?.addEventListener('click',startVisualTimer);return}
 if(tool==='Random Scholar'){const chosen=students[Math.floor(Math.random()*students.length)];openDialog('Random Scholar',chosen?`<div class="center gold" style="font-size:48px;font-weight:900;margin:24px">🎲 ${escapeHtml(chosen.name)}</div>`:'<p>No scholars are loaded.</p>',`<button class="btn btn-secondary" data-close-dialog>Close</button><button class="btn btn-primary" id="pick-another-student">Pick another</button>`);dialogRoot.querySelector('#pick-another-student')?.addEventListener('click',()=>launchClassroomTool('Random Scholar'));return}
 if(tool==='Group Maker'){openDialog('Group Maker',`<div class="field"><label>Students per group</label><input id="tool-group-size" type="number" min="2" max="8" value="4"></div><div id="tool-group-output" class="stack mt-12"></div>`,`<button class="btn btn-secondary" data-close-dialog>Close</button><button class="btn btn-primary" id="make-tool-groups">Make groups</button>`);dialogRoot.querySelector('#make-tool-groups')?.addEventListener('click',makeClassGroups);return}
 if(tool==='Number Picker'){openDialog('Number Picker',`<div class="form-grid"><div class="field"><label>Minimum</label><input id="tool-number-min" type="number" value="1"></div><div class="field"><label>Maximum</label><input id="tool-number-max" type="number" value="100"></div></div><div id="tool-number-output" class="center gold" style="font-size:72px;font-weight:900;margin:18px">?</div>`,`<button class="btn btn-secondary" data-close-dialog>Close</button><button class="btn btn-primary" id="pick-tool-number">Pick number</button>`);dialogRoot.querySelector('#pick-tool-number')?.addEventListener('click',pickClassNumber);return}
 if(tool==='Focus Screen'){openDialog('Focus Screen',`<div class="field"><label>Direction to project</label><textarea id="tool-focus-text">Eyes on the speaker. Voices off. Be ready to learn.</textarea></div>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-primary" id="show-focus-screen">Project direction</button>`);dialogRoot.querySelector('#show-focus-screen')?.addEventListener('click',showFocusScreen);return}
 if(tool==='Attention Signal'){showProjectedMessage('📣','Eyes up. Voices off. Ready to listen.');playAttentionTone();return}
 if(tool==='Ambient Sound'){openDialog('Ambient Sound',`<p>Starts a quiet, locally generated calm tone. No student data or outside service is used.</p><div class="row"><button class="btn btn-primary" id="start-ambient-sound">Start calm sound</button><button class="btn btn-danger" id="stop-ambient-sound">Stop</button></div>`);dialogRoot.querySelector('#start-ambient-sound')?.addEventListener('click',startAmbientSound);dialogRoot.querySelector('#stop-ambient-sound')?.addEventListener('click',stopAmbientSound);return}
 if(tool==='Volume Meter'){openDialog('Volume Meter',`<p>The browser will ask for microphone permission. Audio stays on this device and is not recorded.</p><div style="height:38px;border:1px solid #8aa;border-radius:20px;overflow:hidden"><div id="volume-meter-fill" style="height:100%;width:0;background:linear-gradient(90deg,#38d996,#ffe26b,#ff637e)"></div></div>`,`<button class="btn btn-secondary" data-close-dialog>Close</button><button class="btn btn-primary" id="start-volume-meter">Start meter</button><button class="btn btn-danger" id="stop-volume-meter">Stop</button>`);dialogRoot.querySelector('#start-volume-meter')?.addEventListener('click',startVolumeMeter);dialogRoot.querySelector('#stop-volume-meter')?.addEventListener('click',stopVolumeMeter);return}
 if(tool==='Quick Poll'){openQuickPoll();return}
}
function openQuickPoll(){
 const poll=state.operations?.poll;
 if(poll?.active){
  const max=Math.max(1,...poll.counts);
  openDialog('Quick Poll — Live Results',`<div class="pass-card"><b>${escapeHtml(poll.question)}</b><p>${poll.total} response${poll.total===1?'':'s'} received</p></div><div class="stack mt-12">${poll.choices.map((choice,index)=>{const count=poll.counts[index]||0,pct=poll.total?Math.round(count/poll.total*100):0;return `<article class="pass-card"><div class="row between"><b>${escapeHtml(choice)}</b><span>${count} • ${pct}%</span></div><progress class="dw-progress" max="${max}" value="${count}" aria-label="${escapeHtml(choice)} responses">${count}</progress></article>`}).join('')}</div>`,`<button class="btn btn-secondary" data-close-dialog>Keep poll open</button><button class="btn btn-secondary" id="refresh-quick-poll">Refresh results</button><button class="btn btn-danger" id="close-quick-poll">Close poll</button>`);
  dialogRoot.querySelector('#refresh-quick-poll')?.addEventListener('click',openQuickPoll);
  dialogRoot.querySelector('#close-quick-poll')?.addEventListener('click',async()=>{try{await integrationController.closePoll();closeDialog();showToast('Quick Poll closed.')}catch(err){showToast(err?.message||'Quick Poll could not close.')}});
  return;
 }
 openDialog('Launch Quick Poll',`<div class="field"><label>Question</label><input id="quick-poll-question" maxlength="500" placeholder="What should the class choose?"></div><div class="form-grid mt-12">${[1,2,3,4].map(index=>`<div class="field"><label>Choice ${index}${index>2?' (optional)':''}</label><input data-quick-poll-choice maxlength="120" placeholder="Choice ${index}"></div>`).join('')}</div><p class="muted">Students will see this in Class Poll. Each scholar can submit one response.</p>`,`<button class="btn btn-secondary" data-close-dialog>Cancel</button><button class="btn btn-primary" id="launch-quick-poll">Launch to class</button>`);
 dialogRoot.querySelector('#launch-quick-poll')?.addEventListener('click',async()=>{const button=dialogRoot.querySelector('#launch-quick-poll'),question=dialogRoot.querySelector('#quick-poll-question')?.value||'',choices=[...dialogRoot.querySelectorAll('[data-quick-poll-choice]')].map(input=>input.value);if(button){button.disabled=true;button.textContent='Launching…'}try{await integrationController.launchPoll(question,choices);closeDialog();showToast('Quick Poll launched to the class.')}catch(err){if(button){button.disabled=false;button.textContent='Launch to class'}showToast(err?.message||'Quick Poll could not launch.')}});
}
function startVisualTimer(){clearInterval(classroomToolTimer);let seconds=Math.max(1,Math.min(180,Number(dialogRoot.querySelector('#tool-timer-minutes')?.value)||10))*60;const display=()=>{const el=dialogRoot.querySelector('#tool-timer-display');if(el)el.textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`};display();classroomToolTimer=setInterval(()=>{seconds--;display();if(seconds<=0){clearInterval(classroomToolTimer);classroomToolTimer=null;playAttentionTone();showToast('Classroom timer finished.')}},1000)}
function makeClassGroups(){const size=Math.max(2,Math.min(8,Number(dialogRoot.querySelector('#tool-group-size')?.value)||4)),pool=[...students].sort(()=>Math.random()-.5),groups=[];for(let i=0;i<pool.length;i+=size)groups.push(pool.slice(i,i+size));const out=dialogRoot.querySelector('#tool-group-output');if(out)out.innerHTML=groups.map((group,index)=>`<div class="pass-card"><b>Group ${index+1}</b><p>${escapeHtml(group.map(row=>row.name).join(' • '))}</p></div>`).join('')}
function pickClassNumber(){const min=Number(dialogRoot.querySelector('#tool-number-min')?.value)||0,max=Number(dialogRoot.querySelector('#tool-number-max')?.value)||100,low=Math.min(min,max),high=Math.max(min,max),value=Math.floor(Math.random()*(high-low+1))+low;const out=dialogRoot.querySelector('#tool-number-output');if(out)out.textContent=String(value)}
function showProjectedMessage(icon,message){closeDialog();const overlay=document.createElement('div');overlay.style.cssText='position:fixed;inset:0;z-index:99999;display:grid;place-items:center;text-align:center;padding:7vw;background:radial-gradient(circle,#243d78,#06091c 65%);color:white;cursor:pointer';overlay.innerHTML=`<div><div style="font-size:110px">${icon}</div><div style="font-size:clamp(34px,6vw,84px);font-weight:1000;line-height:1.15">${escapeHtml(message)}</div><p>Click anywhere to close</p></div>`;overlay.addEventListener('click',()=>overlay.remove());document.body.append(overlay)}
function showFocusScreen(){showProjectedMessage('🎯',dialogRoot.querySelector('#tool-focus-text')?.value||'Focus and be ready to learn.')}
function playAttentionTone(){try{const Context=window.AudioContext||window.webkitAudioContext,ctx=new Context();[660,880].forEach((frequency,index)=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.frequency.value=frequency;gain.gain.setValueAtTime(.08,ctx.currentTime+index*.18);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+index*.18+.25);osc.connect(gain);gain.connect(ctx.destination);osc.start(ctx.currentTime+index*.18);osc.stop(ctx.currentTime+index*.18+.26)});setTimeout(()=>ctx.close(),700)}catch{}}
function startAmbientSound(){stopAmbientSound();try{const Context=window.AudioContext||window.webkitAudioContext;ambientContext=new Context();[174,261.63,349.23].forEach(frequency=>{const osc=ambientContext.createOscillator(),gain=ambientContext.createGain();osc.type='sine';osc.frequency.value=frequency;gain.gain.value=.012;osc.connect(gain);gain.connect(ambientContext.destination);osc.start()});showToast('Calm classroom sound started.')}catch{showToast('Ambient sound is not available in this browser.')}}
function stopAmbientSound(){try{ambientContext?.close()}catch{}ambientContext=null;showToast('Ambient sound stopped.')}
async function startVolumeMeter(){stopVolumeMeter();try{volumeStream=await navigator.mediaDevices.getUserMedia({audio:true});const Context=window.AudioContext||window.webkitAudioContext,ctx=new Context(),source=ctx.createMediaStreamSource(volumeStream),analyser=ctx.createAnalyser(),data=new Uint8Array(analyser.frequencyBinCount);source.connect(analyser);const tick=()=>{analyser.getByteFrequencyData(data);const avg=data.reduce((sum,value)=>sum+value,0)/data.length,fill=dialogRoot.querySelector('#volume-meter-fill');if(fill)fill.style.width=`${Math.min(100,avg*1.8)}%`;volumeAnimation=requestAnimationFrame(tick)};tick();volumeStream._dwContext=ctx}catch(err){showToast(err?.message||'Microphone access was not available.')}}
function stopVolumeMeter(){if(volumeAnimation)cancelAnimationFrame(volumeAnimation);volumeAnimation=null;try{volumeStream?.getTracks().forEach(track=>track.stop());volumeStream?._dwContext?.close()}catch{}volumeStream=null;const fill=dialogRoot.querySelector('#volume-meter-fill');if(fill)fill.style.width='0'}
function showReference(){const path=references[state.page];if(!path){openDialog('Reference discrepancy',`<p>The supplied teacher screenshot set does not contain a distinct visible Pass Control design. The file named <code>dragonswood-teacher-05-pass-control.jpg</code> visibly shows <b>Class Rewards & Goals</b>.</p><p>This Pass Control page therefore follows the Master Bible requirements and shared teacher visual system instead of inventing a fake “exact” source.</p>`);return}const overlay=document.createElement('div');overlay.className='reference-overlay';overlay.innerHTML=`<button class="btn btn-gold reference-close">Close reference</button><img src="${path}" alt="Approved reference screenshot for current teacher page">`;document.body.appendChild(overlay);overlay.querySelector('button').addEventListener('click',()=>overlay.remove())}
window.addEventListener('hashchange',()=>{if(integrationSession.status==='authorized')render()});
(async function bootstrapIntegration(){
 if(!window.DWV33Integration){integrationSession={status:'error',message:'Integration runtime did not load.'};render();return}
 integrationController=await window.DWV33Integration.startTeacher(session=>{integrationSession=session;if(session.status==='authorized')applyTeacherSession(session);render()});
})();
